/**
 * Unit tests for the TenantConfigMagicLinkEnabledAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantConfigMagicLinkEnabledAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that isMagicLinkEnabled returns null on a freshly created holder.
     */
    public function testMagicLinkEnabledNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigMagicLinkEnabledAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isMagicLinkEnabledAssigned());
        $this->assertNull($holder->isMagicLinkEnabled());
    }
}
class ImplWithTenantConfigMagicLinkEnabledAttributeHolderUnitTest
